package com.wenkrang.famara.render.scene;
import com.wenkrang.famara.TestPaths;
import com.google.gson.GsonBuilder;
import com.wenkrang.famara.render.platform.ActorAssets;
import com.wenkrang.famara.render.schedule.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.file.*;
import java.util.zip.ZipFile;

/** Exhaustive offline resource/geometry coverage, executed only under the test server. */
public final class ActorCoverageMain {
    public static void main(String[] args)throws Exception {
        Path root=TestPaths.ROOT,out=Path.of(args[0]).toAbsolutePath().normalize();if(!Path.of("").toAbsolutePath().equals(root) || !out.startsWith(root.resolve("diagnostics/famara-p10-all")) || Files.exists(out))throw new IllegalArgumentException("New test output required");Files.createDirectories(out);
        Path source=Path.of(args[1]);var memory=new RenderMemoryBudget(128L*1024*1024);var cpu=new CpuBudget(2000,100,System::nanoTime);var rows=new ArrayList<Map<String,Object>>();int failures=0;
        try(var worker=new BudgetedWorkRunner(128,1_000_000,1_000_000,cpu);var assets=new ActorAssets(memory,worker,cpu)) {
            assets.base(source);assets.prepare();
            for(String type:new TreeSet<>(VanillaActorRegistry.types())){var a=LivingActorTest.actor(type,0,0);var row=new LinkedHashMap<String,Object>();row.put("entity",type);rows.add(row);try(var batch=assets.batch()){var mesh=batch.bake(List.of(a)).toCompletableFuture().get(10,TimeUnit.SECONDS).getFirst();if(mesh.model().quads().isEmpty())throw new AssertionError("Empty living model");row.put("faces",mesh.model().quads().size());row.put("textures",mesh.textures().keySet());row.put("status","PASS");}catch(Throwable e){row.put("status","FAIL");row.put("error",reason(e));failures++;}}
            List<String> items;try(var zip=new ZipFile(source.toFile())){items=zip.stream().map(java.util.zip.ZipEntry::getName).filter(n->n.startsWith("assets/minecraft/items/") && n.endsWith(".json")).map(n->"minecraft:"+n.substring("assets/minecraft/items/".length(),n.length()-5)).sorted().toList();}
            for(String item:items){if(item.equals("minecraft:air"))continue;var base=LivingActorTest.actor("PLAYER",0,0);var actor=equipment(base,Map.of("MAINHAND",FrozenItem.vanilla(item)));var row=new LinkedHashMap<String,Object>();row.put("item",item);rows.add(row);try(var batch=assets.batch()){var mesh=batch.bake(List.of(actor)).toCompletableFuture().get(10,TimeUnit.SECONDS).getFirst();if(mesh.model().quads().size()<=72)throw new AssertionError("Non-air held item produced no mesh");row.put("faces",mesh.model().quads().size());row.put("status","PASS");}catch(Throwable e){row.put("status","FAIL");row.put("error",reason(e));failures++;}}
            Map<String,List<String>> variants=Map.ofEntries(Map.entry("PARROT",List.of("red","blue","green","cyan","gray")),Map.entry("CAT",List.of("tabby","black","red","siamese","british_shorthair","calico","persian","ragdoll","white","jellie","all_black")),Map.entry("AXOLOTL",List.of("lucy","wild","gold","cyan","blue")),Map.entry("RABBIT",List.of("brown","white","black","black_and_white","gold","salt_and_pepper","the_killer_bunny")),Map.entry("HORSE",List.of("white","creamy","chestnut","brown","black","gray","dark_brown")),Map.entry("LLAMA",List.of("creamy","white","brown","gray")),Map.entry("FOX",List.of("red","snow")),Map.entry("FROG",List.of("warm","cold","temperate")),Map.entry("COW",List.of("warm","cold","temperate")),Map.entry("PIG",List.of("warm","cold","temperate")),Map.entry("CHICKEN",List.of("warm","cold","temperate")),Map.entry("PANDA",List.of("normal","lazy","worried","playful","brown","weak","aggressive")),Map.entry("COPPER_GOLEM",List.of("unaffected","exposed","weathered","oxidized")),Map.entry("WOLF",List.of("pale","woods","ashen","black","chestnut","rusty","spotted","striped","snowy")));
            for(var entry:variants.entrySet())for(String value:entry.getValue()){
                var a=LivingActorTest.actor(entry.getKey(),0,0);var varied=new FrozenActor(a.id(),a.type(),a.position(),a.bodyYaw(),a.headYaw(),a.pitch(),a.pose(),false,1,0,"",0xffffff,"",false,false,15,0,new ActorAppearance(Map.of("variant",value),Map.of()),FrozenEquipment.EMPTY);var row=new LinkedHashMap<String,Object>();row.put("variant",entry.getKey()+"/"+value);rows.add(row);
                try(var batch=assets.batch()){batch.bake(List.of(varied)).toCompletableFuture().get(10,TimeUnit.SECONDS);row.put("status","PASS");}catch(Throwable e){row.put("status","FAIL");row.put("error",reason(e));failures++;}
            }
            for(String type:List.of("ARMADILLO","AXOLOTL","BEE","CAMEL","CAT","CHICKEN","COW","DOLPHIN","DONKEY","DROWNED","FOX","GOAT","HAPPY_GHAST","HOGLIN","HORSE","HUSK","LLAMA","MOOSHROOM","MULE","NAUTILUS","OCELOT","PANDA","PIG","PIGLIN","POLAR_BEAR","RABBIT","SHEEP","SNIFFER","SQUID","GLOW_SQUID","STRIDER","SULFUR_CUBE","TRADER_LLAMA","TURTLE","VILLAGER","WOLF","ZOGLIN","ZOMBIE","ZOMBIE_HORSE","ZOMBIE_VILLAGER","ZOMBIFIED_PIGLIN")){
                var a=LivingActorTest.actor(type,0,0);var young=new FrozenActor(a.id(),a.type(),a.position(),180,180,0,"STANDING",true,1,0,"",0xffffff,"",false,false,15,0,new ActorAppearance(Map.of("variant",Set.of("PIG","CHICKEN","COW").contains(type)?"cold":""),Map.of()),FrozenEquipment.EMPTY);var row=new LinkedHashMap<String,Object>();row.put("baby",type);rows.add(row);try(var batch=assets.batch()){batch.bake(List.of(young)).toCompletableFuture().get(10,TimeUnit.SECONDS);row.put("status","PASS");}catch(Throwable e){row.put("status","FAIL");row.put("error",reason(e));failures++;}
            }
            for(String variant:variants.get("WOLF"))for(String state:List.of("tamed","angry"))for(boolean baby:List.of(false,true)){
                var a=LivingActorTest.actor("WOLF",0,0);var wolf=new FrozenActor(a.id(),a.type(),a.position(),180,180,0,"STANDING",baby,1,0,"",0xffffff,"",false,false,15,0,new ActorAppearance(Map.of("variant",variant,state,"true"),Map.of()),FrozenEquipment.EMPTY);var row=new LinkedHashMap<String,Object>();row.put("wolfState",variant+"/"+state+"/baby="+baby);rows.add(row);try(var batch=assets.batch()){batch.bake(List.of(wolf)).toCompletableFuture().get(10,TimeUnit.SECONDS);row.put("status","PASS");}catch(Throwable e){row.put("status","FAIL");row.put("error",reason(e));failures++;}
            }
            for(String pattern:List.of("kob","sunstreak","snooper","dasher","brinely","spotty","flopper","stripey","glitter","blockfish","betty","clayfish")){
                var a=LivingActorTest.actor("TROPICAL_FISH",0,0);var fish=new FrozenActor(a.id(),a.type(),a.position(),180,180,0,"STANDING",false,1,0,"",0xffffff,"",false,false,15,0,new ActorAppearance(Map.of("pattern",pattern,"bodyColor","16711680","patternColor","255"),Map.of()),FrozenEquipment.EMPTY);var row=new LinkedHashMap<String,Object>();row.put("fishPattern",pattern);rows.add(row);try(var batch=assets.batch()){var mesh=batch.bake(List.of(fish)).toCompletableFuture().get(10,TimeUnit.SECONDS).getFirst();boolean large=Set.of("flopper","stripey","glitter","blockfish","betty","clayfish").contains(pattern);if(mesh.textures().keySet().stream().noneMatch(k->k.path().equals("entity/fish/tropical_"+(large?"b":"a"))))throw new AssertionError("Fish body texture did not match model");row.put("status","PASS");}catch(Throwable e){row.put("status","FAIL");row.put("error",reason(e));failures++;}
            }
            Map<String,String> worn=new TreeMap<>();for(String item:items)for(var entry:Map.of("_helmet","HEAD","_chestplate","CHEST","_leggings","LEGS","_boots","FEET").entrySet())if(item.endsWith(entry.getKey()))worn.put(item,entry.getValue());
            for(var armor:worn.entrySet()){var row=new LinkedHashMap<String,Object>();row.put("wornArmor",armor.getKey());rows.add(row);try(var batch=assets.batch()){var mesh=batch.bake(List.of(equipment(LivingActorTest.actor("PLAYER",0,0),Map.of(armor.getValue(),FrozenItem.vanilla(armor.getKey()))))).toCompletableFuture().get(10,TimeUnit.SECONDS).getFirst();if(mesh.model().quads().size()<=72)throw new AssertionError("Armor slot missing");row.put("status","PASS");}catch(Throwable e){row.put("status","FAIL");row.put("error",reason(e));failures++;}}
            for(String pattern:List.of("sentry","dune","coast","wild","ward","eye","vex","tide","snout","rib","spire","wayfinder","shaper","silence","raiser","host","flow","bolt"))for(String material:List.of("quartz","iron","netherite","redstone","copper","gold","emerald","diamond","lapis","amethyst","resin")){
                var row=new LinkedHashMap<String,Object>();row.put("armorTrim",pattern+"/"+material);rows.add(row);var item=new FrozenItem("minecraft:diamond_chestplate","",0xffffff,"minecraft:"+pattern,"minecraft:"+material,true,0,"","",false);
                try(var batch=assets.batch()){var mesh=batch.bake(List.of(equipment(LivingActorTest.actor("PLAYER",0,0),Map.of("CHEST",item)))).toCompletableFuture().get(10,TimeUnit.SECONDS).getFirst();if(mesh.textures().keySet().stream().noneMatch(k->k.path().startsWith("trim/")))throw new AssertionError("Armor trim missing");row.put("status","PASS");}catch(Throwable e){row.put("status","FAIL");row.put("error",reason(e));failures++;}
            }
            for(var spec:List.of(new String[]{"HORSE","minecraft:diamond_horse_armor"},new String[]{"WOLF","minecraft:wolf_armor"},new String[]{"NAUTILUS","minecraft:iron_nautilus_armor"},new String[]{"HAPPY_GHAST","minecraft:red_harness"},new String[]{"LLAMA","minecraft:red_carpet"})){
                var row=new LinkedHashMap<String,Object>();row.put("animalArmor",spec[0]+"/"+spec[1]);rows.add(row);try(var batch=assets.batch()){batch.bake(List.of(equipment(LivingActorTest.actor(spec[0],0,0),Map.of("BODY",FrozenItem.vanilla(spec[1]))))).toCompletableFuture().get(10,TimeUnit.SECONDS);row.put("status","PASS");}catch(Throwable e){row.put("status","FAIL");row.put("error",reason(e));failures++;}
            }
        }
        var report=new LinkedHashMap<String,Object>();report.put("status",failures==0?"PASS":"FAIL");report.put("failures",failures);report.put("cases",rows);report.put("memoryAfterClose",memory.snapshot());Files.writeString(out.resolve("report.json"),new GsonBuilder().setPrettyPrinting().create().toJson(report)+"\n");System.out.println("cases="+rows.size()+" failures="+failures+" memory="+memory.snapshot().live());if(failures>0 || memory.snapshot().live()!=0)throw new AssertionError("Actor resource coverage failed");
    }
    public static FrozenActor equipment(FrozenActor a,Map<String,FrozenItem> slots){return new FrozenActor(a.id(),a.type(),a.position(),a.bodyYaw(),a.headYaw(),a.pitch(),a.pose(),a.baby(),a.scale(),a.limbSwing(),a.variant(),a.tintRgb(),a.skinUrl(),a.slim(),a.sheared(),a.sky(),a.block(),a.appearance(),new FrozenEquipment(slots,false));}
    private static String reason(Throwable error){while(error.getCause()!=null)error=error.getCause();return error.toString();}
}
